import React, { useState } from 'react';
import { chatWithIntelligentAI } from '../services/intelligentChatbot';

const ChatbotDemo = () => {
  const [question, setQuestion] = useState('');
  const [response, setResponse] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [topic, setTopic] = useState('Tech Trends');

  const testQuestions = [
    "What is the difference between frontend and backend?",
    "What is React?",
    "What is Node.js?",
    "What is a database?",
    "What is the speed of light?",
    "What is DNA?",
    "What is artificial intelligence?",
    "What is blockchain?"
  ];

  const handleTest = async (testQuestion) => {
    setQuestion(testQuestion);
    setIsLoading(true);
    
    try {
      const result = await chatWithIntelligentAI(testQuestion, topic, []);
      setResponse(result);
    } catch (error) {
      setResponse(`Error: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCustomTest = async () => {
    if (!question.trim()) return;
    
    setIsLoading(true);
    try {
      const result = await chatWithIntelligentAI(question, topic, []);
      setResponse(result);
    } catch (error) {
      setResponse(`Error: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="card" style={{ maxWidth: '800px', margin: '20px auto' }}>
      <h2 style={{ textAlign: 'center', marginBottom: '30px' }}>
        🤖 Chatbot Training Demo
      </h2>

      <div style={{ marginBottom: '20px' }}>
        <label style={{ display: 'block', marginBottom: '10px', fontWeight: 'bold' }}>
          Select Topic:
        </label>
        <select
          value={topic}
          onChange={(e) => setTopic(e.target.value)}
          style={{
            padding: '8px 12px',
            borderRadius: '6px',
            border: '1px solid #e2e8f0',
            fontSize: '1rem',
            width: '200px'
          }}
        >
          <option value="Tech Trends">Tech Trends</option>
          <option value="Science">Science</option>
          <option value="Wellness">Wellness</option>
          <option value="History">History</option>
          <option value="Geography">Geography</option>
          <option value="Literature">Literature</option>
          <option value="Mathematics">Mathematics</option>
          <option value="Art">Art</option>
        </select>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <h3>Quick Test Questions:</h3>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', marginBottom: '20px' }}>
          {testQuestions.map((q, index) => (
            <button
              key={index}
              onClick={() => handleTest(q)}
              disabled={isLoading}
              style={{
                padding: '8px 12px',
                background: '#667eea',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                fontSize: '0.9rem',
                opacity: isLoading ? 0.6 : 1
              }}
            >
              {q.substring(0, 30)}...
            </button>
          ))}
        </div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <h3>Custom Test:</h3>
        <div style={{ display: 'flex', gap: '10px', marginBottom: '10px' }}>
          <input
            type="text"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            placeholder="Ask any question..."
            style={{
              flex: 1,
              padding: '10px 12px',
              borderRadius: '6px',
              border: '1px solid #e2e8f0',
              fontSize: '1rem'
            }}
            onKeyPress={(e) => e.key === 'Enter' && handleCustomTest()}
          />
          <button
            onClick={handleCustomTest}
            disabled={isLoading || !question.trim()}
            style={{
              padding: '10px 20px',
              background: isLoading || !question.trim() ? '#cbd5e0' : '#48bb78',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: isLoading || !question.trim() ? 'not-allowed' : 'pointer',
              fontSize: '1rem',
              fontWeight: 'bold'
            }}
          >
            {isLoading ? 'Testing...' : 'Test'}
          </button>
        </div>
      </div>

      {response && (
        <div style={{
          padding: '20px',
          background: '#f7fafc',
          borderRadius: '8px',
          border: '1px solid #e2e8f0'
        }}>
          <h3 style={{ marginBottom: '10px', color: '#2d3748' }}>
            🤖 Chatbot Response:
          </h3>
          <p style={{ 
            lineHeight: '1.6', 
            color: '#4a5568',
            margin: 0,
            whiteSpace: 'pre-wrap'
          }}>
            {response}
          </p>
        </div>
      )}

      <div style={{
        marginTop: '20px',
        padding: '15px',
        background: '#e6fffa',
        borderRadius: '8px',
        border: '1px solid #81e6d9'
      }}>
        <h4 style={{ margin: '0 0 10px 0', color: '#234e52' }}>
          💡 How It Works:
        </h4>
        <ul style={{ margin: 0, paddingLeft: '20px', color: '#234e52' }}>
          <li>Chatbot searches knowledge base for keyword matches</li>
          <li>Uses pattern recognition for related questions</li>
          <li>Provides cross-topic answers when relevant</li>
          <li>Falls back to contextual responses when needed</li>
        </ul>
      </div>
    </div>
  );
};

export default ChatbotDemo;
